create table public.personal_media(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,storage_path text not null,original_name text not null,mime_type text not null,media_kind text not null check(media_kind in('photo','video','audio','document','other')),size_bytes bigint not null default 0 check(size_bytes>=0),visibility text not null default 'private' check(visibility in('private','connections','public')),caption text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,storage_path)); alter table public.personal_media enable row level security; create policy personal_media_owner on public.personal_media for all to authenticated using(auth.uid()=owner_id) with check(auth.uid()=owner_id); grant select,insert,update,delete on public.personal_media to authenticated; insert into storage.buckets(id,name,public,file_size_limit) values('personal-media','personal-media',false,1073741824) on conflict(id) do update set public=false; create policy personal_media_storage_read on storage.objects for select to authenticated using(bucket_id='personal-media' and (storage.foldername(name))[1]=auth.uid()::text); create policy personal_media_storage_insert on storage.objects for insert to authenticated with check(bucket_id='personal-media' and (storage.foldername(name))[1]=auth.uid()::text); create policy personal_media_storage_update on storage.objects for update to authenticated using(bucket_id='personal-media' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='personal-media' and (storage.foldername(name))[1]=auth.uid()::text); create policy personal_media_storage_delete on storage.objects for delete to authenticated using(bucket_id='personal-media' and (storage.foldername(name))[1]=auth.uid()::text);